INSERT INTO "public"."card" ("id", "columnId", "rank", "title") VALUES ($1, $2, ((SELECT CASE WHEN n > 999999999 THEN NULL ELSE length(n::text)::text || n::text || rtrim(lpad(floor(random() * 1000000)::bigint::text, 6, '0'), '0') END FROM (SELECT CASE WHEN k IS NULL OR left(k, 1) = '0' THEN 0 ELSE substr(k, 2, substr(k, 1, 1)::int)::bigint + 1 END AS n FROM (SELECT MAX("rank") AS k FROM "public"."card" WHERE "columnId" = $3 AND "rank" ~ '^[0-9]{2,}$') AS m) AS x)), NULL) RETURNING "id" AS "id", "columnId" AS "columnId", "rank" AS "rank", "title" AS "title";
-- ["b","c1","c1"]
